const xml = typeof $input.item.json.data === 'string' ? $input.item.json.data : JSON.stringify($input.item.json);
const items = [];
const re = /<item>([\s\S]*?)<\/item>/g;
let m;
while ((m = re.exec(xml)) !== null) {
  const block = m[1];
  const title  = (block.match(/<title>(?:<!\[CDATA\[)?([\s\S]*?)(?:\]\]>)?<\/title>/) || [])[1] || '';
  const link   = (block.match(/<link>([\s\S]*?)<\/link>/) || block.match(/<guid[^>]*>([\s\S]*?)<\/guid>/) || [])[1] || '';
  const pubD   = (block.match(/<pubDate>([\s\S]*?)<\/pubDate>/) || [])[1] || '';
  const src    = (block.match(/<source[^>]*>([\s\S]*?)<\/source>/) || [])[1] || '';
  const desc   = (block.match(/<description>(?:<!\[CDATA\[)?([\s\S]*?)(?:\]\]>)?<\/description>/) || [])[1] || '';
  const titulo = title.replace(/<[^>]*>/g,'').replace(/&amp;/g,'&').replace(/&lt;/g,'<').replace(/&gt;/g,'>').trim();
  const linkClean = link.trim();
  if (!titulo || !linkClean) continue;
  let dateStr = '';
  try { dateStr = pubD ? new Date(pubD.trim()).toISOString().slice(0,10) : ''; } catch {}
  const fonte = src.replace(/<[^>]*>/g,'').trim() || ((() => { try { return new URL(linkClean).hostname; } catch { return ''; } })());
  const resumo = desc.replace(/<[^>]*>/g,'').replace(/&amp;/g,'&').trim().slice(0,200);
  items.push({ titulo, link: linkClean, fonte, data: dateStr || new Date().toISOString().slice(0,10), resumo });
}
return items.slice(0,8).map(it => ({ json: it }));

const raw = $input.item.json.noticias || [];
const vistos = new Set();
const noticias = [];
for (const item of raw) {
  const it = item.titulo ? item : (item.json || {});
  if (!it.titulo || !it.link || vistos.has(it.link)) continue;
  vistos.add(it.link);
  noticias.push(it);
}
const hojeStr = new Date().toLocaleDateString('pt-BR', { weekday:'long', day:'numeric', month:'long', year:'numeric' });
const lista = noticias.slice(0,20).map((n,i) =>
  (i+1) + '. [' + n.titulo + '] — Fonte: ' + n.fonte + ' — Data: ' + n.data + '
Resumo: ' + (n.resumo || 'sem resumo')
).join('

');
const prompt = 'Você é um assistente de marketing jurídico para o escritório Falaw (advocacia trabalhista e empresarial, Brasil). Hoje é ' + hojeStr + '.

Analise as notícias abaixo e selecione as 8 mais relevantes para um escritório de advocacia trabalhista e empresarial. Para cada uma, retorne um JSON com os campos:
- "idx": número original (1-based)
- "tema": título atrativo para conteúdo do escritório (máx 80 chars)
- "angle": por que é relevante para empresários/empregados (máx 120 chars)
- "tipo": um de "blog", "redes_sociais" ou "informativo"
- "prioridade": 1=alta 2=media 3=baixa

Retorne APENAS um array JSON, sem markdown.

Notícias:
' + lista;
return [{ json: { noticias, prompt } }];

const r = $input.item.json;
const noticias = $('Preparar Prompt IA').item.json.noticias || [];
const hoje10 = new Date().toISOString().slice(0,10);
let classificados = [];
try {
  const raw = r.choices?.[0]?.message?.content || '';
  classificados = JSON.parse(raw.replace(/```json|```/g,'').trim());
} catch(e) {
  classificados = noticias.slice(0,8).map((n,i) => ({ idx: i+1, tema: n.titulo.slice(0,80), angle: n.resumo.slice(0,120), tipo: 'informativo', prioridade: 2 }));
}
const sugestoes = classificados
  .filter(c => c.idx >= 1 && c.idx <= noticias.length)
  .sort((a,b) => (a.prioridade||2) - (b.prioridade||2))
  .map(c => {
    const n = noticias[c.idx - 1];
    const id = 'sug_' + hoje10.replace(/-/g,'') + '_' + String(c.idx) + '_' + Math.random().toString(36).slice(2,6);
    return { id, tema: c.tema || n.titulo, angle: c.angle || '', tipo: c.tipo || 'informativo', prioridade: c.prioridade || 2, link: n.link, fonte: n.fonte, dataNoticia: n.data, dataSugestao: hoje10, status: 'pendente' };
  });
return sugestoes.map(s => ({ json: s }));

